# 테스트 피라미드 예시: Python 3에서 실행 가능한 코드
tests = {"unit": 120, "integration": 25, "e2e": 6}
print(tests["unit"] > tests["integration"] > tests["e2e"])

# 통합 테스트(Integration Test) 예시: Python 3에서 실행 가능한 코드
def save_and_load(value):
    store = {"key": value}
    return store["key"]
assert save_and_load("data") == "data"
print("ok")

# 승인 테스트 예시: Python 3에서 실행 가능한 코드
criteria = {"can_login": True, "can_pay": True}
print(all(criteria.values()))

# 테스트 더블(Test Double) 예시: Python 3에서 실행 가능한 코드
class FakeClock:
    def now(self):
        return "2026-05-07"
print(FakeClock().now())

# 페이크(Fake) 예시: Python 3에서 실행 가능한 코드
class MemoryRepo:
    def __init__(self): self.items = []
    def add(self, x): self.items.append(x)
repo = MemoryRepo(); repo.add(1); print(repo.items)

# 테스트 픽스처 예시: Python 3에서 실행 가능한 코드
fixture = {"user": "kim", "role": "admin"}
print(fixture["role"])

# 테스트 격리 예시: Python 3에서 실행 가능한 코드
def test_case():
    local_state = []
    local_state.append("x")
    return len(local_state)
print(test_case())

# 브랜치 커버리지 예시: Python 3에서 실행 가능한 코드
branches = {"true": True, "false": False}
tested = {"true", "false"}
print(tested == set(branches))

# 기술 부채 측정 예시: Python 3에서 실행 가능한 코드
debt = {"duplication": 3, "complexity": 5, "outdated": 2}
print(sum(debt.values()))

# 메서드 추출 예시: Python 3에서 실행 가능한 코드
def subtotal(items):
    return sum(items)
print(subtotal([100, 200]))

# 가드 절(Guard Clause) 예시: Python 3에서 실행 가능한 코드
def discount(age):
    if age < 0:
        return 0
    return 1000 if age < 13 else 0
print(discount(10))

# 시스템 이해를 위한 테스트 예시: Python 3에서 실행 가능한 코드
def rule(value):
    return value.strip().lower()
print(rule(" A "))

# 코드 고정(Seam) 예시: Python 3에서 실행 가능한 코드
def get_time(clock):
    return clock()
print(get_time(lambda: "fixed-time"))

# 변경 불안 극복 예시: Python 3에서 실행 가능한 코드
safety = {"tests": True, "small_step": True, "rollback": True}
print(all(safety.values()))

# API 문서화 예시: Python 3에서 실행 가능한 코드
api = {"path": "/users", "method": "GET", "status": 200}
print(api["method"], api["path"])

# 아키텍처 결정 기록(ADR) 예시: Python 3에서 실행 가능한 코드
adr = {"decision": "use-postgres", "status": "accepted"}
print(adr["status"])

# 행동 주도 개발(BDD) 예시: Python 3에서 실행 가능한 코드
scenario = {"given": "cart has item", "when": "checkout", "then": "order created"}
print(scenario["then"])

# 인수 테스트 주도 개발(ATDD) 예시: Python 3에서 실행 가능한 코드
acceptance = {"login": True, "receipt": True}
print(all(acceptance.values()))

# 세션 기반 테스팅 예시: Python 3에서 실행 가능한 코드
session = {"charter": "checkout edge cases", "minutes": 60}
print(session["charter"])

# 리스크 기반 테스팅 예시: Python 3에서 실행 가능한 코드
risks = {"payment": 9, "theme": 2}
print(max(risks, key=risks.get))
